	title 'Desk Manager--CDACalls'************************************************************************ Desk Manager--CDACalls  * for the Apple II GS** original CDA code by John Worthinton.* original NDA code by Steven Glass** Additions and alterations by Steven Glass and* Konstantin Othmer*** This file contains**	SaveScreen*	svscreen*	RestScreen*	rstscreen*	SaveAll*	svmousstate*	rstmousstate*	RestAll*	InstCDA*	MyDeref*	GrowTable*	RemoveCDA*	SetDAStrPtr*	GetDAStrPtr**********************************************************************************************************************************************			         **	Copyright (C) 1985-1988	         **	All Rights Reserved		         **	Apple Computer, Inc.	         **			         *********************************************************************************************************************************************** Change History*** 11 February 87	  Steven Glass**    Both SaveScreen and RestoreScreen went to EndCall0*    when complete but had not pushed D	on the stack.*    They now use oEndCall0.** 26-Sep-90	Dave Lyons** Changed setmode8 to shortmx, setmode16 to longmx.***********************************************************************	include 'all.macros'	include '::sys.equs.asm'	include 'e16.memory';=================================================;; Special Macros;	MACRO&lab	movelong &src,&dest&lab	lda &src	sta &dest	lda &src+2	sta &dest+2	mendDAVersionNumber	equ $8300	;8300	include 'Desk.Equates.asm'; Desk Manager memory usage; The desk manager has 4.5k of dedicated ram in bank E0.; The memory (from $E0/0C00 to $E0/DFFF) is used as follows:; bank 00 text screen saved at $E0/0C00; bank 01 text screen saved at $E0/1000; bank E0 text screen saved at $E0/1400; bank E1 text screen saved at $E0/1800; zero page (bank 00 page 00) saved at $E0/1C00; desk manager data	space is 1 page starting at $E0/1D00****************************************************************	longa on	longi on****************************************************************;;    svscreen -- save the 80-col text screen;;    Note that the quick entry points don't save the bank.;    When the routine returns the data bank is set to E0.;    If you really want the data bank preserved, use the tool;    entries.; This is the tool call for saving the screen. The desk manager; currently calls the svscreen directly. Is this wrong?!?savescreen	PROC EXPORT	phb	jsr svscreen	plb	jml oEndCall0	; right end call 11	Feb 87 SEG	ENDPsvscreen	PROC EXPORT	longmx	ldx #$400	;save bank 00 main	ldy #$0C00	lda #$3FF	mvn $000000,$E00000	ldx #$400	;save bank 00 aux	ldy #$1000	lda #$3FF	mvn $010000,$E00000	ldx #$400	;save bank E0 main	ldy #$1400	lda #$3FF	mvn $E00000,$E00000	ldx #$400	;save bank E0 aux	ldy #$1800	lda #$3FF	mvn $E10000,$E00000	rts	ENDP****************************************************************;;    RestoreScreen -- restore the 80-col text screen in;	  bank 00 and bank E0;;    Same note as above. If you wnat the data bank preserved, call;    restorescreen,	instead of rstscreen.; This is the tool entry to rstscreen. Should the manager use this too?restScreen	PROC EXPORT	phb	jsr rstscreen	plb	jml oEndCall0	; right end call 11	Feb 87	ENDPrstscreen	PROC EXPORT	longmx	ldx #$07loop	cpx |mymslot	beq @1	cpx #$03	beq @1	jsr copysholes@1	dex	bne loop	ldx #$C00	;restore bank 0 main	ldy #$400	lda #$3FF	mvn $E00000,$000000	ldx #$1000	;restore bank 0 aux	ldy #$400	lda #$3FF	mvn $E00000,$010000	ldx #$1400	;restore bank E0 main	ldy #$400	lda #$3FF	mvn $E00000,$E00000	ldx #$1800	;restore bank E0 aux	ldy #$400	lda #$3FF	mvn $E00000,$E10000	rtscopysholes	shortmx	lda >$000478,x	sta >$E01478,x	sta >$E00C78,x	lda >$0004F8,x	sta >$E014F8,x	sta >$E00CF8,x	lda >$000578,x	sta >$E01578,x	sta >$E00D78,x	lda >$0005F8,x	sta >$E015F8,x	sta >$E00DF8,x	lda >$000678,x	sta >$E01678,x	sta >$E00E78,x	lda >$0006F8,x	sta >$E016F8,x	sta >$E00EF8,x	lda >$000778,x	sta >$E01778,x	sta >$E00F78,x	lda >$0007F8,x	sta >$E017F8,x	sta >$E00FF8,x	longmx	rts	ENDP************************************************************************     saveall  -- save the state information prior to*                 activating the desk accessory.** Change History** 3 Jun 87     JW and SEG** When SaveAll and RestoreAll deal with	mmode, it is possible* for the code to become confused.  The	code that looks for* the mouse card initializes the mmode word in 8 bit mode.* It later reads the word in 16 bit mode and if the* uninitialized byte powered up with the high bit set,* then the code thinks the mouse is off	even when it is on.** The fix here is to always zero the mmode before calling* the old code.***********************************************************************saveall	PROC EXPORT	lda #0	sta >mmode	shortmx	phb	pla	sta >bregsave	lda #$E0	; set data bank reg	to $E0	pha	plb	lda #$00	sta |intstatus; Make sure that main memory, etc is set correctly.	lda |statereg	; set memory state	sta |svstatereg	lda #$0C	sta |statereg	; mega // kludge; The code here should save the interrupt info, so we can handle; multiple desk accessories.	phb	lda |intstatus	longmx	bpl czz	jmp cantopenczz	beq int2a	ldx #irq_intflag**$FFFF	ldy #int1ay**$FFFF	bra czz1int2a	ldx #irq_intflag**$FFFF	ldy #int2ay**$FFFFczz1	lda #$0C	mvn $E10000,$E00000	shortmx	ldy |intstatus	lda >irq_mousvbl	sta |mousvblsv,y	longmx	tya	beq int2b	ldx #irq_a**$FFFF	ldy #int1by**$FFFF	bra czz2int2b	ldx #irq_a**$FFFF	ldy #int2by**$FFFFczz2	lda #$13	mvn $E10000,$E00000	plb	phd	;save the direct page and set	pla	; it to page 00 bank 00.	sta |dirpgsv	lda #$00	pha	pld	shortmx; Save the video mode softswitches.	lda |rd80col	sta |col80sv	lda |newvideo	sta |newvidsv	longmx	lda |rdtext	;save rdtext and rdmix	sta |txtsv	lda |rdpage2	;save rdpage2 and rdhires	sta |page2sv	lda |altcharset	;save altcharset and rd80vid	sta |altcharsv; Save the 80-col text screens. Note that the mvn instruction; will leave the data bank register set	to $E0	longa on	longi on	jsr svscreen; Save zero page (bank 00 page 00) and the 80-col video; screens.	ldx #$0000	; save zp and stack	ldy #$1C00	lda #$FF	mvn $000000,$E00000; Save the mouse info. Note that the //e mouse card has to; be special cased.	** need to add code	for that **; note that svmousstate must be called with 16-bit m and x.	jsr svmousstate	lda >cursor	sta |cursorsave; Initialize the 80-col firmware. Note that the desk manager; uses the basic entry points, as does the control panel.; Uses the fake 40-col stuff if the user has that set as a; preference.	shortmx	sec	jsl tobramsetup	lda |rdc3rom	sta |c3romsv	lda |newvideo	and #%01111111	sta |newvideo	sta |txtset	sta |mixclr	sta |txtpage1	lda #$FF	sta >$000032	; inverse switch	longmx	pha	; space for result	pha	pha	_GetOutputDevice	pla	sta |oldoutdev	; save old output globals	pla	sta |oldoutdev+2	pla	sta |oldoutdev+4	pha	; save the old output device	pha	; so we don't have any problems	_GetOutGlobals	pla	sta |oldoutglob	pla	sta |oldoutglob+2	pha	; save the old input device	pha	pha	_GetInputDevice	pla	sta |oldindev	pla	sta |oldindev+2	pla	sta |oldindev+4	pha	; save the oldinput	globals too	pha	_GetInGlobals	pla	sta |oldinglob	pla	sta |oldinglob+2	pea $FF	; and mask	pea $00	; or mask	_SetOutGlobals	bcc cz1;	brk 01	dc.b 0,1cz1	pea 00	; device type	pushlong #$03	; pointer to driver	_SetOutputDevice	bcc loop1;	brk 02	dc.b 0,2loop1	shortmx	ldx #$00	; check for 80-col card in placeloop4card	lda $C305	cmp #$38	bne nocard	lda $C307	cmp #$18	bne nocard	inx	bne loop4card	bra cz2nocard	sta |setintc3rom	; just to make sure	its really in	bra loop4cardcz2	longmx	pea 01	; init device to output	_inittextdev	bcc cz3;	brk 03	dc.b 0,3cz3	PushWord #00	PushWord #$19	; want 40 cols	_ReadBParam	pla	sta |sv4080	bne cont1	pea $11	_writecharcont1	lda #$00	pha	plb	plb	cli	jml oEndCall0cantopen		brk $FF	ENDP****************************************************************;;    svmousstate --	save the clamp values of the mouse.;; This routine should save the clamp values for the mouse.; The intent is to make this routine function for both the; FDB mouse and the	//e mouse card. The	diagnostic calls for the; mouse card need to be added.svmousstate	PROC EXPORT; Cn0C : 20; CnFB : D6	lda #$C700	sta |slotloop		; 	lda |slot	pha	shortmx	ldy #$0C	lda (1,s),y	cmp #$20	bne miss	ldy #$FB	lda (1,s),y	cmp #$D6	beq gotitmiss	longmx	pla	lda |slot	xba	dec a	cmp #$C0	beq fail	xba	sta |slot	bra loopfail		; 	lda #$FFFF	sta |mmode	bra exitgotit	longmx	pla	xba	and #$0F	sta |mymslot	; push mouse slot for init call	clc	adc #$7F8	tax	longa off	longi on	sep #$20	lda 0,x	beq noton	sta |mmode	shortmx	lda >mouseslot	pha	lda |mymslot	sta >mouseslot	longmx	lda #$00	pha	_setmouse	bra saveclampsnoton	longmx	lda #$00	sta |mmode	bra exitsaveclamps	PushWord #00	PushWord #00	PushWord #00	PushWord #00	_getmouseclamp	pla	sta |hiyclampsv	pla	sta |loyclampsv	pla	sta |hixclampsv	pla	sta |loxclampsv	shortmx	pla	sta >mouseslot	longmxexit	rts	ENDP****************************************************************;;    rstmousstate -- save the clamp values of the mouse.;; Note that the diagnostic calls for the //e mouse card need to; be added.rstmousstate	PROC EXPORT	lda |mmode	bmi noton	beq noton	shortmx	lda >mouseslot	pha	lda |mymslot	sta >mouseslot	longmx	lda |mmode	pha	_setmouse	lda |loxclampsv	pha	lda |hixclampsv	pha	lda |loyclampsv	pha	lda |hiyclampsv	pha	_clampmouse	shortmx	pla	sta >mouseslot	longmxnoton	rts	ENDP****************************************************************;;   restall -- put everything back the way it was.;;   called on exit from the desk managerrestall	PROC EXPORT	sei	;turn off interrupts; set data bank reg	to $E0	shortmx	lda #$E0	pha	plb; Restore the 80 col video switches. There might be more to	be added; here.	lda |col80sv	bmi a1	sta |clr80col	bra conta1	sta |set80colcont	lda |vid80sv	bmi a2	sta |clr80vid	bra cont2a2	sta |set80vid; This code will restore the old interrupt info. Currently,	it is; saved so that the	desk accessory interrupt is semi-reentrant.; Not currently supported.cont2	phb	lda |intstatus	longmx	beq int2a	ldx #int1ay**$FFFF	ldy #irq_intflag**$FFFF	bra cz1int2a	ldx #int2ay**$FFFF	ldy #irq_intflag**$FFFFcz1	lda #$0C	mvn $E00000,$E10000	shortmx	plb	ldy |intstatus	lda |mousvblsv,y	sta >irq_mousvbl	phb	longmx	tya	beq int2b	ldx #int1by**$FFFF	ldy #irq_a**$FFFF	bra cz2int2b	ldx #int2by**$FFFF	ldy #irq_a**$FFFFcz2	lda #$13	mvn $E00000,$E10000; Restore the 80-col text screens	jsr rstscreen; Bank 00 page 00 restored.	ldx #$1C00	;restore the zero page	ldy #$0000	lda #$FF	mvn $E00000,$000000	plb; restore the mouse	clamps etc. Currently, I'm only supporting; the FDB mouse. Will fix ...	jsr rstmousstate	;restore mouse clamps; restore the cursor	lda |cursorsave	sta >cursor; restore the direct page	lda |dirpgsv	;restore the direct	page	pha	pld; Restore the data bank to what it was before the desk accessory	shortmx	lda |newvidsv	and #$C0	ora |newvideo	sta |newvideo	lda |altcharsv	bpl aa1	sta |setaltchar	bra aa2aa1	sta |clraltcharaa2	lda |txtsv	bpl aa3	sta |txtset	bra aa4aa3	sta |txtclraa4	lda |mixsv	bpl aa5	sta |mixset	bra aa6aa5	sta |mixclraa6	lda |page2sv	bpl aa7	sta |txtpage2	bra aa8aa7	sta |txtpage1aa8	lda |hiressv	bpl aa9	sta |hires	bra aa10aa9	sta |loresaa10	lda |c3romsv	bpl aa11	sta |setslotc3rom	bra rstmemaa11	sta |setintc3rom	longmx	lda |oldoutdev+4	pha	lda |oldoutdev+2	pha	lda |oldoutdev	pha	_SetOutputDevice	lda |oldoutglob+2	pha	lda |oldoutglob	pha	_SetOutGlobals	lda |oldindev+4	pha	lda |oldindev+2	pha	lda |oldindev	pha	_SetInputDevice	lda |oldinglob+2	pha	lda |oldinglob	pha	_setinglobals	shortmx; Restore the old memory state.rstmem	lda |svstatereg	sta |statereg	;mega // kludge	longmx	PushWord #0	PushWord #$20	;want 40 cols	_ReadBParam	pla	shortmx	bne fast	lda >irq_shadow+1	and #%01111111	sta >irq_shadow+1	bra checkvolfast	lda >irq_shadow+1	ora #%10000000	sta >irq_shadow+1checkvol	longmx	PushWord #0	PushWord #$1E	_ReadBParam	pla	shortmx	sta >irq_volume	lda >bregsave	pha	plbexit	longmx	jml oEndCall0	ENDP************************************************************************ procedure InstallCDA (DAHandle : Handle);** Takes a handle to the da to install on the stack** Change History** 25 Jul 88	Steven Glass** Error code was loaded into a-reg instead of x-reg.  Fixed today.** * 10 Oct 88	Konstantin Othmer** Since scrollable menu was added, number of CDAs is no longer limited* so this routine no longer returns an error code.** Also temp1 and temp2 changed to MyTemp1 and MyTemp2 so zero page is no * longer destroyed.** 25 Oct 88	Steven Glass** Moved code to unlock the handle into growtable.  Don't bother locking* and unlocking in this routine any more.***********************************************************************InstCDA	PROC EXPORT	DefineStackOrigD	word	;2MyTemp1	long	;4MyTemp2	long	;8ret1	block 3ret2	block 3DAHandle	long	pha	; push 8 bytes of work space on stack	pha	pha	pha	phd	; save d-reg		tsc	; make stack into direct page	tcd	phb	; save dbr	pea $E0E0	plb	plb	lda |roomleft	; number of da's before we grow	lsr a	lsr a	; if less than 4 then grow	bne cont	jsr growtablecont	lda |cdatabhndl	; dereference the handle	sta Mytemp1	lda |cdatabhndl+2	sta Mytemp1+2	jsr MyDeref	lda |numdas	; # of da's currently installed	asl a	asl a	tay	lda DAHandle	; get lo part	sta [Mytemp2],y	lda DAHandle+2	; get hi part	iny	iny	sta [Mytemp2],y	dec |roomleft	inc |numdas	; increment number of da's installed			plb	pld		pla	pla	pla	pla	jml oEndCall4	ENDP*****************************************************************MyDeref	PROC EXPORT** This routine is used by both InstallCDA and RemoveCDA to* dereference the handle in MyTemp1 and put the pointer in * MyTemp2.** The direct page layout is the same for InstallCDA, RemoveCDA* and this call.*** Inputs:*	MyTemp1** Outputs:*	MyTemp2** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStack	;(same as InstallCDA and RemoveCDA)OrigD	wordMyTemp1	longMyTemp2	longret1	block 3ret2	block 3DAHandle	long	ldy #0002	lda [Mytemp1]	sta Mytemp2	lda [Mytemp1],y	sta Mytemp2+2	rts	ENDP*****************************************************************growtable	PROC EXPORT** This routine is called when the table of CDAs needs to* be grown.  It makes the handle $20 bytes bigger and * increments RoomLeft by 8.*** Inputs:*	CDATabHndl*	RoomLeft** Outputs:*	RoomLeft** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 25 Oct 88	Steven Glass** No longer uses direct page.*****************************************************************;-----------------------------------------------------------;; Make sure the table is not locked.;	pushlong |cdatabhndl	_hunlock	;-----------------------------------------------------------;; Get the table size.;	pha	pha	pushlong |cdatabhndl	_gethandlesize;-----------------------------------------------------------;; Add $20 and set the size.;	lda 1,s	; bump the size by $20	clc	adc #$0020	sta 1,s	lda 3,s	adc #$0000	sta 3,s	pushlong |cdatabhndl	_sethandlesize;-----------------------------------------------------------;; Bump room left.;	lda |roomleft	clc	adc #$08	sta |roomleft	rts	ENDP***************************************************************** RemoveCDA -- takes a handle to the da to remove on the stack** Change History** 05 Oct 88	Added by Konstantin Othmer*RemoveCDA	PROC EXPORT	DefineStackOrigD	wordMyTemp1	longMyTemp2	longret1	block 3ret2	block 3DAHandle	long	pha	; push 8 bytes of work space on stack	pha	pha	pha	phd	; save d-reg	tsc	; make stack into direct page	tcd	phb	pea $E0E0	plb	plb		pushlong |cdatabhndl ; push handle to da table	_hlock	; lock the handle	lda |cdatabhndl	; dereference the handle	sta Mytemp1	lda |cdatabhndl+2	sta Mytemp1+2	jsr Myderef	;try to find this handle in the list	ldy #0	;beginning of listfindCDA	tya	lsr a	lsr a	;convert index to da number	cmp |numdas	bne cont1	;if we've checked the whole list, branch	brl AllDone	cont1	lda DAHandle	; get lo part	cmp [Mytemp2],y	bne notit	iny	iny	lda DAHandle+2	; get hi part	cmp [Mytemp2],y	bne notit1	;we found it.  Move all CDA's at [temp2],y+4 to [temp2],y; currently y points to hi part of da to replacemove1	iny	iny	;bump to lo part of next cda	tya	lsr a	lsr a		cmp |numdas	;check if there are more to move	beq RemoveDone	lda [Mytemp2],y	;low part of CDA we want to move	tax	iny	iny	;bump to high part	lda [Mytemp2],y	;get high part	dey	dey	;back to low part	dey	dey	;high part of previous	sta [Mytemp2],y	;save high part	dey	dey	txa	sta [Mytemp2],y	;save low part of previous	iny	iny	;back to high part of previous	iny	iny	;low part of next da to replace	iny	iny	;high part of next da	bra move1;this isn't it.  Align pointer to next CDA entry.notit		;lo word didn't match: branches here	iny	iny	notit1		;high word didn't match: branch here	iny	iny	bra findCDA	RemoveDone	dec |numdas	inc |roomleft	;unlock handle and then check to see if we can free up some space	pushlong |cdatabhndl	_hunlock	ldx #0	;no error	lda |roomleft	; number of da's before we grow	cmp #20	;if there is room for 20 more, shrink by 12	bcc ShrinkDone	;branch if there is room for 20 or less	;here we shrink the CDA handle size	pushlong #$00	pushlong |cdatabhndl	_gethandlesize	pla	sec	sbc #$20	sta Mytemp1	pla	sbc #$00	sta Mytemp1+2	pushlong Mytemp1	pushlong |cdatabhndl	_sethandlesize	lda |roomleft	sec	sbc #$08	sta |roomleft	ldx #0	;no error	bra ShrinkDone	AllDone		pushlong |cdatabhndl	_hunlock	ldx #daNotFound	;not found error: $0510	ShrinkDone		;handle has already been unlocked			plb	pld	pla	pla	pla	pla	jml oErrOut4	ENDP************************************************************************ setdastrptr** This routine will	takes a pointer on the stack and will* install it in dastrptr** dastrptr points to the strings to be printed for the* 2 builtin desk accessories -- Control	Panel and Quit, as* well as the title	string for the desk	manager** The pointer should point to a table containing pointers* to c style strings (hi-bit on, zero terminated). The first* entry in the table contains a pointer	to the title string, the second* a pointer to the name of the control panel. The final string points to* the name used for	the quit option***********************************************************************setdastrptr	PROC EXPORT	DefineStackTemp	LONGOrigB	BYTEOrigD	WORDRet1	block 3Ret2	block 3strptr	longdahand	long	phd	; save d-reg	phb	; save b-reg	pha	; 4 bytes on stack	pha	tsc	; turn stack into d-page	tcd		pea $E0E0	; set bank to $E0	plb	plb	lda strptr	; move strptr into final location	sta |dastrptr	lda strptr+2	sta |dastrptr+2	lda |cdatabhndl+2	; copy handle to temp	sta temp+2	lda |cdatabhndl	sta temp	ldy #4	; lock the handle	lda [temp],y	ora #$8000	sta [temp],y	ldy #2	; deref the handle	lda [temp],y	tax	lda [temp]	sta temp	stx temp+2	ldy #$0002	; copy the passed handle into the	lda dahand	; first location in the derefed	sta [temp]	; table	lda dahand+2	sta [temp],y	lda |cdatabhndl+2	; unlock the handle	sta temp+2	lda |cdatabhndl	sta temp	ldy #0004	lda [temp],y	and #$7fff	sta [temp],y	pla	; clean off the stack (4 bytes)	pla	plb	; b-reg	pld	; d-reg	jml oEndCall8	; call strip routine to strip inputs	ENDP; returns the current value of dastrptrgetdastrptr	PROC EXPORTret1	equ 1ret2	equ ret1+3strptrlo	equ ret2+3strptrhi	equ strptrlo+2	lda >dastrptr	sta strptrlo,s	lda >dastrptr+2	sta strptrhi,s	jml oEndCall0	ENDP	END